window.VN_LEARNING['lesson-13']={
version:1,title:'Vegetarian Diets for Older People',chapter:'Chapter 15 + current healthy-ageing guidance',duration:'80–95 minutes',
outcomes:['Explain why declining energy needs can coexist with stable or higher nutrient density needs.','Connect protein distribution and resistance activity with preservation of muscle and function.','Plan reliable vitamin B12, vitamin D, calcium, hydration and food strategies for older vegetarians.','Assess barriers involving appetite, oral health, dexterity, medicines, access and social isolation.','Individualize recommendations and recognize when disease, weight loss or functional decline needs clinical care.'],
modules:[
{id:'ageing',title:'Reframe changing needs',summary:'Keep nutrient density high as appetite, energy expenditure and function change.',moments:[
{id:'l13-m1',title:'Lower energy need does not mean lower nutrient need',highYield:'Many older adults need fewer calories while still needing similar or greater attention to protein, vitamin D, B12, calcium and nutrient density.',teaching:['Energy expenditure may fall with less activity, reduced lean mass and other ageing changes, but the timing is individual—not a switch at age 50. Nutrient needs do not decline in parallel. Smaller appetites can make each meal and snack more important.','Assessment should distinguish intended energy reduction from unplanned weight loss. Loss of appetite, chewing or swallowing difficulty, depression, medicines, illness, food insecurity and social isolation can all reduce intake.'],keyPoints:['Energy need may decline gradually.','Nutrient density remains important.','Age thresholds are not precise.','Unplanned weight loss is a warning sign.'],visual:{title:'The ageing nutrition tension',kind:'comparison',items:[{label:'Often less',detail:'Energy expenditure and appetite'},{label:'Still essential',detail:'Protein, micronutrients, fluids and food quality'},{label:'Sometimes greater attention',detail:'B12, vitamin D, calcium and muscle-supporting intake'},{label:'Monitor',detail:'Weight, function, intake and symptoms'}]},mnemonic:{title:'Less energy, not less care',cue:'Density rises as room falls',explanation:'When appetite or energy need is lower, each eating opportunity must work harder.'},goodToKnow:'A smaller body or appetite does not prove that a person should lose weight; goals depend on health, function and history.',practiceConnection:'Screen unplanned loss, early satiety and functional decline before offering generic portion reduction.',activity:{prompt:'Which statement best describes ageing nutrition?',options:[{text:'Energy needs may fall while nutrient density remains crucial',correct:true,feedback:'Correct. Nutrient needs do not simply shrink with calories.'},{text:'All vitamin needs decline with age',correct:false,feedback:'Several nutrients require equal or greater attention.'},{text:'Every person’s metabolism drops abruptly at age 50',correct:false,feedback:'Ageing changes are gradual and individual.'}]}},
{id:'l13-m2',title:'Function is a primary nutrition outcome',highYield:'Strength, mobility, cognition, independence and quality of life matter alongside body weight and laboratory values.',teaching:['Muscle strength supports rising from a chair, carrying groceries, balance and recovery from illness. Bone health supports mobility and fracture prevention. Hydration, vision, cognition and oral function influence whether someone can shop, cook and eat safely.','Vegetarian planning should ask what the person can do, not only what they consume. A complete menu on paper is ineffective if the person cannot open packages, chew the food, remember supplements or reach the store.'],keyPoints:['Track strength and mobility.','Assess oral and cognitive function.','Connect food access with independence.','Plans must fit actual ability.'],visual:{title:'Function pathway',kind:'sequence',items:[{label:'Access',detail:'Obtain and afford food'},{label:'Prepare',detail:'Open, cut, cook and store safely'},{label:'Consume',detail:'Appetite, chewing and swallowing'},{label:'Use',detail:'Digest, absorb and metabolize'},{label:'Function',detail:'Strength, mobility, cognition and independence'}]},mnemonic:{title:'A-P-C-U-F',cue:'Access · Prepare · Consume · Use · Function',explanation:'Trace where an apparently good plan can break down.'},goodToKnow:'Soy beverage, soup and other foods count toward fluid intake; the claim that soymilk “does not count” is false.',practiceConnection:'New swallowing difficulty, recurrent choking, confusion or rapid functional decline requires qualified evaluation.',activity:{prompt:'Which follow-up measure best captures functional nutrition benefit?',options:[{text:'Improved ability to prepare meals and rise from a chair',correct:true,feedback:'Correct. Function is a meaningful outcome.'},{text:'Owning a printed menu',correct:false,feedback:'A menu does not prove it can be used.'},{text:'Avoiding all fortified foods',correct:false,feedback:'Fortification may be highly useful.'}]}}
]},
{id:'muscle',title:'Protect muscle and bone',summary:'Combine adequate protein, distribution, loading and bone nutrients.',moments:[
{id:'l13-m3',title:'Protein quality, distribution and resistance work together',highYield:'Reducing protein simply because someone is older can accelerate risk; many healthy older adults benefit from at least about 1.0 g/kg/day plus resistance activity, individualized for health.',teaching:['Ageing muscle may respond less robustly to small protein doses. A varied vegetarian pattern can distribute meaningful protein across meals using soy foods, legumes, seitan where suitable, nuts, seeds, grains, eggs or dairy as included. Adequate total energy prevents protein from being diverted as fuel.','Resistance exercise provides the stimulus for muscle maintenance. Protein targets must be individualized for kidney disease, acute illness, frailty, body size and clinical goals; a population benchmark is not a prescription for every person.'],keyPoints:['Do not routinely reduce protein with age.','Distribute useful amounts across meals.','Pair intake with resistance activity.','Individualize for disease and frailty.'],visual:{title:'Muscle maintenance equation',kind:'map',items:[{label:'Protein amount',detail:'Enough total intake for the person'},{label:'Protein distribution',detail:'Meaningful sources at multiple meals'},{label:'Energy',detail:'Enough fuel to spare protein'},{label:'Resistance stimulus',detail:'Appropriate strength activity'},{label:'Recovery',detail:'Sleep, health and rehabilitation context'}]},mnemonic:{title:'A-D-E-R',cue:'Amount · Distribution · Energy · Resistance',explanation:'Four levers for muscle support.'},goodToKnow:'The 2025 Academy adult position notes benefits around at least 1.0 g/kg/day in healthy older adults, but clinical conditions can change the goal.',practiceConnection:'Coordinate protein and exercise planning with medical and rehabilitation teams when kidney disease, frailty or recent hospitalization is present.',activity:{prompt:'Which plan best supports muscle in a healthy older vegetarian adult?',options:[{text:'Adequate distributed protein plus appropriate resistance exercise',correct:true,feedback:'Correct. Nutrition and loading work together.'},{text:'Reduce protein at every meal because of age alone',correct:false,feedback:'Routine restriction can work against muscle preservation.'},{text:'Use protein while total energy remains severely inadequate',correct:false,feedback:'Energy adequacy is also necessary.'}]}},
{id:'l13-m4',title:'Bone protection needs more than calcium',highYield:'Calcium, vitamin D, protein, resistance/weight-bearing activity and fall prevention form an integrated bone plan.',teaching:['Bone loss can accelerate after menopause, but timing and magnitude differ. Calcium-rich foods and verified fortification are important, while vitamin D supports calcium regulation and often needs explicit supplementation according to jurisdiction and individual risk.','Protein and loading support the musculoskeletal system; fall risk, vision, medicines, home hazards and balance determine whether low bone strength becomes a fracture. Supplements should not replace review of the full risk picture.'],keyPoints:['Verify calcium sources.','Plan vitamin D explicitly.','Include protein and loading.','Address falls and medicines.'],visual:{title:'Bone-to-fracture pathway',kind:'sequence',items:[{label:'Bone substrate',detail:'Calcium, protein and overall nutrition'},{label:'Regulation',detail:'Vitamin D and health factors'},{label:'Loading',detail:'Weight-bearing and resistance activity'},{label:'Fall exposure',detail:'Balance, vision, medicines and environment'},{label:'Outcome',detail:'Maintain function and reduce fracture risk'}]},mnemonic:{title:'C-D-P-L-F',cue:'Calcium · D · Protein · Loading · Falls',explanation:'Five parts of a practical bone plan.'},goodToKnow:'A blanket statement that most older people require the same calcium supplement is too absolute; food intake, vitamin D status, medications and clinical risk matter.',practiceConnection:'Refer for osteoporosis and fall-risk assessment when history, fracture, height loss or functional concerns suggest risk.',activity:{prompt:'Which intervention addresses the widest bone-health picture?',options:[{text:'Calcium/vitamin D adequacy, protein, loading and fall prevention',correct:true,feedback:'Correct. Fracture risk is multi-factorial.'},{text:'Calcium alone with no review of falls or vitamin D',correct:false,feedback:'This is incomplete.'},{text:'Avoid all weight-bearing movement',correct:false,feedback:'Appropriate loading supports bone and function.'}]}}
]},
{id:'micronutrients',title:'Make B12, vitamin D and hydration explicit',summary:'Age-related absorption and access issues can affect every dietary pattern.',moments:[
{id:'l13-m5',title:'B12 risk rises beyond vegetarian status',highYield:'Older adults may absorb food-bound B12 less efficiently; deficiency risk can occur in omnivores and vegetarians alike.',teaching:['Reduced gastric acid, pernicious anemia, GI surgery and some medicines can impair B12 absorption. Vegans also lack natural dietary B12 unless fortified foods or supplements are used. Neurologic and blood effects can occur, and symptoms such as cognitive change, neuropathy or fatigue are not specific enough for self-diagnosis.','Fortified foods and supplements provide free B12 that does not require release from food protein in the same way. Serum B12 is commonly used and methylmalonic acid can help clarify borderline status under clinical direction.'],keyPoints:['Age can impair food-bound B12 absorption.','Vegans need a reliable source.','Symptoms are not diagnostic.','Clinical testing can clarify status.'],visual:{title:'B12 risk pathways',kind:'map',items:[{label:'Low intake',detail:'No animal foods and unreliable fortification'},{label:'Poor release',detail:'Low gastric acid or medicines'},{label:'Poor intrinsic factor',detail:'Pernicious anemia or gastric condition'},{label:'Altered absorption',detail:'Ileal disease or surgery'},{label:'Outcome',detail:'Blood and neurologic effects'}]},mnemonic:{title:'I-R-F-A',cue:'Intake · Release · Factor · Absorption',explanation:'Four places B12 status can fail.'},goodToKnow:'Older adults may be advised to obtain much of their B12 from fortified foods or supplements; the exact plan should reflect jurisdiction and clinical context.',practiceConnection:'New neuropathy, gait change, cognitive symptoms or macrocytic anemia concerns require medical assessment rather than a food-only trial.',activity:{prompt:'Why can an omnivorous older adult still develop B12 deficiency?',options:[{text:'Age-related or medical changes can impair release and absorption',correct:true,feedback:'Correct. Intake is only one part of B12 status.'},{text:'B12 never occurs in animal foods',correct:false,feedback:'Animal foods contain B12, but absorption may still fail.'},{text:'Soy automatically destroys B12',correct:false,feedback:'Soy is not the mechanism described.'}]}},
{id:'l13-m6',title:'Hydration and nutrient access need practical systems',highYield:'Thirst sensation, mobility, continence concerns, medicines and cognition can reduce drinking even when fluids are available.',teaching:['Water, fortified beverages, soups and other drinks contribute fluid. Needs vary with climate, illness, renal or cardiac status, medicines and activity. Fear of incontinence or difficulty reaching the toilet can lead to intentional restriction.','Make drinking accessible: preferred fluids within reach, light containers, routine prompts and fluid-rich foods. Do not prescribe a universal volume when a person has a clinical fluid restriction or altered needs.'],keyPoints:['Many beverages and foods count as fluid.','Thirst may be less reliable.','Access and continence affect intake.','Clinical restrictions require individualization.'],visual:{title:'Hydration barrier check',kind:'map',items:[{label:'Signal',detail:'Reduced thirst or cognition'},{label:'Access',detail:'Reach, containers and assistance'},{label:'Tolerance',detail:'Swallowing, nausea or preferences'},{label:'Concern',detail:'Continence or bathroom access'},{label:'Clinical',detail:'Heart, kidney, medicines and fluid orders'}]},mnemonic:{title:'S-A-T-C-C',cue:'Signal · Access · Tolerance · Concern · Clinical',explanation:'Five reasons “drink more” may not be enough.'},goodToKnow:'Fortified soy beverage contributes both fluid and nutrients; it is not excluded from hydration simply because it contains food components.',practiceConnection:'Sudden confusion, very low urine, dizziness or suspected dehydration requires timely clinical assessment.',activity:{prompt:'Which hydration strategy is most individualized?',options:[{text:'Use preferred accessible fluids and account for health conditions and continence barriers',correct:true,feedback:'Correct. Hydration advice must fit the person.'},{text:'Require one identical volume for every older adult',correct:false,feedback:'Needs and restrictions differ.'},{text:'Exclude soup and soy beverage from all fluid estimates',correct:false,feedback:'They generally contribute fluid.'}]}}
]},
{id:'implementation',title:'Remove barriers and coordinate care',summary:'Adapt food, environment and follow-up to the person’s function and conditions.',moments:[
{id:'l13-m7',title:'Oral health, dexterity and isolation can change the diet',highYield:'Difficulty chewing, opening, shopping or eating alone can create malnutrition risk even when nutrition knowledge is excellent.',teaching:['Dental pain, dry mouth and poorly fitting dentures can push people away from vegetables, nuts, seeds and protein foods. Adapt textures with soups, stews, mashed beans, tofu, smooth nut/seed butters, fortified beverages and soft cooked foods while addressing the underlying oral issue.','Arthritis, tremor, vision change and low stamina can affect packaging and cooking. Social isolation, bereavement and limited income can reduce appetite and variety. Delivery services, community meals, adapted tools and shared meals may be nutrition interventions.'],keyPoints:['Assess chewing and swallowing.','Adapt texture without losing density.','Check packaging and cooking ability.','Address isolation and access.'],visual:{title:'Barrier-to-adaptation map',kind:'comparison',items:[{label:'Chewing',detail:'Soft protein foods and oral care referral'},{label:'Dexterity',detail:'Easy-open packages, prepared components and adapted tools'},{label:'Shopping',detail:'Delivery, transport and shelf-stable backups'},{label:'Isolation',detail:'Shared meals and community programs'}]},mnemonic:{title:'C-D-S-I',cue:'Chewing · Dexterity · Shopping · Isolation',explanation:'Four practical barriers to ask about.'},goodToKnow:'A soft diet can still be high in protein and nutrient density; texture modification does not have to mean tea and toast.',practiceConnection:'Coughing during meals, wet voice, recurrent chest infection or food sticking may indicate swallowing risk and needs qualified assessment.',activity:{prompt:'Which adaptation preserves protein for someone with chewing difficulty?',options:[{text:'Use tofu, smooth hummus, mashed lentils and fortified soy yogurt',correct:true,feedback:'Correct. Texture changes while density remains.'},{text:'Offer only clear tea',correct:false,feedback:'This does not meet nutrition needs.'},{text:'Remove all legumes without replacement',correct:false,feedback:'This reduces options without solving the cause.'}]}},
{id:'l13-m8',title:'Chronic disease changes the plan',highYield:'Vegetarian principles do not override kidney, heart, diabetes, swallowing or medication-specific needs.',teaching:['Kidney disease can change protein, potassium, phosphorus, sodium and fluid goals. Heart failure can alter sodium and fluid plans. Diabetes management requires carbohydrate context, while anticoagulants and other medicines may interact with foods or supplements.','Coordinate with the medical team and avoid assuming that more legumes, greens or fluid is always better. Preserve the person’s vegetarian values within clinically appropriate limits and monitor weight, function, symptoms and laboratory data as directed.'],keyPoints:['Clinical conditions change nutrient targets.','Medicines and supplements can interact.','Preserve values within safe limits.','Use coordinated monitoring.'],visual:{title:'Individualization filter',kind:'sequence',items:[{label:'Vegetarian goals',detail:'Foods, ethics and preferences'},{label:'Clinical condition',detail:'Disease-specific requirements'},{label:'Function',detail:'Appetite, chewing, mobility and cognition'},{label:'Resources',detail:'Support, cost and access'},{label:'Shared plan',detail:'Practical, monitored and revisable'}]},mnemonic:{title:'G-C-F-R-P',cue:'Goals · Condition · Function · Resources · Plan',explanation:'Five filters before recommending a diet change.'},goodToKnow:'A food that is generally nutrient dense can still need portion or preparation changes for a specific medical condition.',practiceConnection:'Do not independently change a prescribed renal, fluid, anticoagulant or diabetes plan without coordination.',activity:{prompt:'What is the safest response when an older vegan adult has advanced kidney disease?',options:[{text:'Coordinate an individualized vegetarian plan with the renal care team',correct:true,feedback:'Correct. Disease-specific targets must guide the pattern.'},{text:'Recommend unlimited high-potassium foods to everyone',correct:false,feedback:'Potassium goals may differ in kidney disease.'},{text:'Abandon vegetarian values without discussion',correct:false,feedback:'Values can often be preserved with careful adaptation.'}]}}
]}
],
caseStudy:{title:'Weight loss after a move',scenario:'A 78-year-old lacto-ovo vegetarian recently moved after a spouse died. They report early fullness, loose dentures and difficulty opening jars. Meals are mostly toast and tea; weight and chair-rise strength have declined. Vitamin B12 and D status have not been reviewed.',prompts:['Which nutrition, functional and social risks are present?','Which soft high-protein foods could fit the person’s pattern?','What B12, vitamin D and bone-health questions need assessment?','Which community, dental and medical supports could help?'],takeaway:'Nutrition in later life succeeds when nutrient targets, function, access, social context and clinical care are solved together.'},
recap:['Energy need may decline while nutrient density remains essential.','Function and unplanned weight change are major outcomes.','Adequate distributed protein and resistance activity support muscle.','Bone health integrates calcium, D, protein, loading and fall prevention.','Older adults can have B12 absorption risk regardless of dietary label.','Many beverages and foods contribute fluid.','Oral, dexterity, shopping and social barriers can drive poor intake.','Chronic disease requires an individualized coordinated vegetarian plan.'],
flashcards:[{front:'Nutrient density',back:'Nutrients supplied relative to energy; especially important when energy needs or appetite are lower.',tag:'ageing'},{front:'Sarcopenia',back:'Age-associated loss of muscle mass, strength and function.',tag:'muscle'},{front:'Protein distribution',back:'Placing meaningful protein sources at more than one meal.',tag:'muscle'},{front:'Resistance exercise',back:'Muscle-loading activity that stimulates maintenance and adaptation.',tag:'muscle'},{front:'Bone plan',back:'Calcium, D, protein, loading and fall prevention.',tag:'bone'},{front:'Food-bound B12 malabsorption',back:'Difficulty releasing B12 from food protein, more common with low acid or some medicines.',tag:'B12'},{front:'Methylmalonic acid',back:'A marker that can help clarify suspected B12 deficiency under clinical direction.',tag:'B12'},{front:'Hydration barrier',back:'A signal, access, tolerance, continence or clinical factor that reduces safe intake.',tag:'hydration'},{front:'Texture adaptation',back:'Changing food consistency while preserving energy, protein and nutrients.',tag:'function'},{front:'Unplanned weight loss',back:'A warning sign requiring assessment of intake, disease, function and social factors.',tag:'risk'},{front:'Clinical individualization',back:'Adapting the vegetarian pattern to disease, medicines, function and monitoring.',tag:'practice'},{front:'Functional outcome',back:'Strength, mobility, cognition, independence or ability to shop/cook/eat.',tag:'practice'}],
practice:[{prompt:'Why can fewer calories require greater nutrient density?',answer:'There is less food volume available to deliver similar or increased nutrient priorities.',rationale:'Needs do not fall in parallel.',tag:'ageing'},{prompt:'Name four muscle-support levers.',answer:'Protein amount, distribution, energy adequacy and resistance activity.',rationale:'Muscle responds to intake and stimulus.',tag:'muscle'},{prompt:'State the five-part bone plan.',answer:'Calcium, vitamin D, protein, loading and fall prevention.',rationale:'Fracture risk is multi-factorial.',tag:'bone'},{prompt:'Why can omnivorous older adults develop B12 deficiency?',answer:'Low acid, pernicious anemia, medicines, surgery or ileal disease can impair release or absorption.',rationale:'Intake is only one step.',tag:'B12'},{prompt:'Do soy beverages count as fluid?',answer:'Yes, unless a specific clinical plan says otherwise.',rationale:'They contribute water and nutrients.',tag:'hydration'},{prompt:'List four practical intake barriers.',answer:'Chewing, dexterity, shopping/access and isolation.',rationale:'Knowledge alone cannot solve them.',tag:'function'},{prompt:'Give three soft high-protein vegetarian foods.',answer:'Tofu, smooth hummus, mashed lentils, soy yogurt, soft eggs or dairy where included.',rationale:'Texture can change without losing density.',tag:'function'},{prompt:'When should protein goals be individualized?',answer:'Kidney disease, acute illness, frailty, body-size changes and other clinical conditions.',rationale:'Population guidance is not a prescription.',tag:'practice'},{prompt:'What makes follow-up functional?',answer:'Track weight plus strength, mobility, intake ability, cognition and independence.',rationale:'Function reflects real-world benefit.',tag:'practice'},{prompt:'Why coordinate chronic-disease care?',answer:'Disease and medicines can alter protein, electrolytes, fluid, carbohydrate and supplement goals.',rationale:'General healthy-food advice may conflict with treatment.',tag:'practice'}]
};

// Evidence-strengthening extension: anabolic resistance, medication context and function-first troubleshooting.
