window.VN_LEARNING['lesson-13'].duration='105–120 minutes';
window.VN_LEARNING['lesson-13'].outcomes.push('Explain how total energy, protein dose, quality, distribution and resistance activity work together in later life.','Identify medication, swallowing, cognition and access factors that can change an otherwise sound vegetarian plan.');
window.VN_LEARNING['lesson-13'].modules.push({id:'advanced-ageing',title:'Troubleshoot the real causes of declining intake and function',summary:'Move beyond nutrient lists to protein physiology, medicines, swallowing, cognition and food access.',moments:[
{id:'l13-m9',title:'Protein planning is a five-lever system—not one magic number',highYield:'In later life, muscle support depends on enough total energy, meaningful protein at several meals, protein quality, resistance activity and clinical context.',teaching:['Ageing muscle may respond less strongly to a small protein dose, a phenomenon often called anabolic resistance. This makes a breakfast with almost no protein and one large protein-heavy dinner less useful than placing meaningful protein foods at more than one eating opportunity. The exact target is individualized: illness, frailty, body size, activity, kidney function and overall intake change the decision.','Plant proteins can support muscle, but the food choice and amount matter. Soy foods, legumes, seitan, textured vegetable protein, mycoprotein where available, nuts and seeds, and dairy or eggs when included can contribute. Protein quality reflects digestibility and indispensable amino-acid profile; variety across the day and adequate portions help. There is no requirement to combine complementary proteins in the same mouthful.','Protein cannot compensate for too little energy, and food alone cannot provide the stimulus of muscle-loading activity. Resistance exercise adapted to ability, adequate energy, sufficient protein and recovery work together. In advanced kidney disease or another condition with prescribed targets, the renal or medical plan takes priority over generic higher-protein advice.'],keyPoints:['Distribute meaningful protein across the day.','Choose concentrated protein foods, not vegetables alone.','Protect total energy intake.','Pair nutrition with safe resistance activity.','Individualize for disease and frailty.'],visual:{title:'Five levers for muscle support',kind:'layers',items:[{label:'Energy',detail:'Enough food energy to avoid using protein as fuel'},{label:'Amount',detail:'A clinically appropriate total intake'},{label:'Distribution',detail:'Meaningful protein at several meals'},{label:'Quality',detail:'Digestibility, indispensable amino acids and varied sources'},{label:'Stimulus',detail:'Resistance or muscle-loading activity adapted to ability'}]},mnemonic:{title:'E-A-D-Q-S',cue:'Energy · Amount · Distribution · Quality · Stimulus',explanation:'Protein works as part of a system.'},goodToKnow:'Plant-rich patterns can support healthy ageing, but a very bulky high-fibre pattern may worsen early fullness in someone already losing weight.',practiceConnection:'Instead of asking only how many grams, map breakfast, lunch, dinner and snacks; then improve the weakest eating opportunity with a tolerated protein-plus-energy option.',activity:{prompt:'Which change best addresses a low-protein breakfast and declining strength?',options:[{text:'Add a tolerated concentrated protein food, protect total energy and connect with an appropriate resistance plan',correct:true,feedback:'Correct. This uses several muscle-support levers together.'},{text:'Add lettuce while leaving energy and protein unchanged',correct:false,feedback:'Lettuce does not solve low energy or protein concentration.'},{text:'Move all daily protein to one late meal',correct:false,feedback:'Distribution across more than one meal is usually more practical for muscle support.'}]}},
{id:'l13-m10',title:'Medicines, swallowing and access can change the nutrition diagnosis',highYield:'When intake declines, the cause may be a medicine schedule, chewing or swallowing problem, cognitive change, grief, transport barrier or food insecurity—not lack of nutrition knowledge.',teaching:['Some medicines and conditions alter nutrient risk or meal timing. Long-term acid suppression and metformin can contribute to B12 risk in some people. Calcium, iron, high-fibre foods and soy can interfere with absorption of levothyroxine when taken too close to the dose; the answer is a consistent clinician- or pharmacist-directed schedule, not automatic avoidance of nutritious foods. People using warfarin are generally counselled toward a consistent vitamin K pattern rather than eliminating green vegetables.','Coughing during meals, a wet voice, repeated chest infections, food sticking, prolonged chewing or unexplained weight loss can signal swallowing difficulty and require prompt assessment. Texture modification must preserve energy, protein, fluids and enjoyment; simply pureeing vegetables can produce a low-energy plan. Dental pain, dry mouth, impaired grip and fatigue can create different but equally important barriers.','Cognitive change, bereavement, isolation, loss of driving, food cost and complex cooking tasks can shrink intake. Ask who shops, who cooks, whether food spoils, which appliances feel safe and whether the person can open packages. Practical supports may include grocery delivery, congregate meals, prepared components, adaptive utensils, caregiver coordination and a visible supplement schedule.'],keyPoints:['Review medication timing and nutrient risk with a pharmacist or clinician.','Do not eliminate greens solely because of warfarin; consistency and monitoring matter.','Treat swallowing signals as referral issues.','Assess shopping, cognition, grief and kitchen function.'],visual:{title:'Why intake fell',kind:'map',items:[{label:'Mouth and swallow',detail:'Pain, dentition, dry mouth, coughing or food sticking'},{label:'Medicines',detail:'Appetite, taste, GI effects, timing and nutrient interactions'},{label:'Mind and mood',detail:'Cognition, depression, grief and motivation'},{label:'Means',detail:'Money, transport, equipment and physical ability'},{label:'Meals',detail:'Who shops, cooks, serves and shares food?'}]},mnemonic:{title:'Five M questions',cue:'Mouth · Medicines · Mind · Means · Meals',explanation:'A function-first screen for declining intake.'},goodToKnow:'The phrase drug–nutrient interaction can mean altered absorption, changed appetite or taste, a food effect on a medicine, or a medicine effect on a nutrient; the response depends on the mechanism.',practiceConnection:'Bring the complete medication and supplement list to a pharmacist or prescriber review. Do not independently change medicine timing, dose or prescribed diet.',activity:{prompt:'An older vegetarian taking warfarin eats leafy greens inconsistently. What is the safest principle?',options:[{text:'Coordinate a consistent vitamin K pattern and monitoring with the anticoagulation team',correct:true,feedback:'Correct. Consistency is generally more useful than blanket elimination.'},{text:'Remove all green vegetables forever without clinical input',correct:false,feedback:'Blanket avoidance can reduce diet quality and is not the usual principle.'},{text:'Double the medicine after a spinach meal',correct:false,feedback:'Medication changes must be clinician directed.'}]}}
]});
window.VN_LEARNING['lesson-13'].flashcards.push({front:'Anabolic resistance',back:'The reduced muscle-building response to a small protein stimulus that can occur with ageing.',tag:'muscle'},{front:'Five muscle levers',back:'Energy, amount, distribution, quality and stimulus.',tag:'muscle'},{front:'Five M intake screen',back:'Mouth, medicines, mind, means and meals.',tag:'assessment'},{front:'Warfarin and greens',back:'Aim for a consistent vitamin K pattern with clinical monitoring rather than automatic elimination.',tag:'medicines'});
window.VN_LEARNING['lesson-13'].practice.push({prompt:'Why is a single protein number not a complete older-adult plan?',answer:'Energy intake, protein distribution and quality, resistance activity, disease, frailty and actual food access also determine the response.',rationale:'Muscle support is a system, not one target.',tag:'muscle'},{prompt:'Use the five M screen for declining intake.',answer:'Ask about mouth or swallowing, medicines, mind or mood, means such as money and transport, and how meals are obtained and prepared.',rationale:'The barrier may be functional or social rather than educational.',tag:'assessment'});
